import zipfile, xml.etree.ElementTree as ET, sys, re
NS='{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
p=sys.argv[1]
z=zipfile.ZipFile(p)
ss=[]
if 'xl/sharedStrings.xml' in z.namelist():
    r=ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in r.findall(f'{NS}si'):
        ss.append(''.join(t.text or '' for t in si.iter(f'{NS}t')))
sheets=[n for n in z.namelist() if re.match(r'xl/worksheets/sheet\d+\.xml$',n)]
for sh in sorted(sheets):
    print(f'=== {sh} ===')
    r=ET.fromstring(z.read(sh))
    for row in r.iter(f'{NS}row'):
        vals=[]
        for c in row.findall(f'{NS}c'):
            t=c.get('t'); v=c.find(f'{NS}v')
            if t=='inlineStr':
                isx=c.find(f'{NS}is'); vals.append(''.join(x.text or '' for x in isx.iter(f'{NS}t')) if isx is not None else '')
            elif v is None: vals.append('')
            elif t=='s': vals.append(ss[int(v.text)])
            else: vals.append(v.text or '')
        print('\t'.join(vals))
